var o=`0216-churros-con-chocolate`;var t=`world-0216`;var n=`ES`;var a=`southern-europe`;var r=8;var l=29;var s={en:`Churros con Chocolate`,ua:`Чурос із шоколадом`};var u={en:`A traditional Spain dish made with all-purpose flour, chicken egg, whole cow milk. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Іспанія. Основні інгредієнти: пшеничне борошно універсальне, куряче яйце, цільне коров'яче молоко. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var h=[{en:`Cook the listed ingredients in simmering water for about 5 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 5 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:5,i:[[`water`,250,`ml`],[`unsalted-butter`,50,`g`],[`white-granulated-sugar`,35,`g`],[`table-salt`,2,`g`]]},{en:`Pour the flour into the hot liquid and beat vigorously until a dough forms; cool briefly, then beat in eggs. Pipe the dough into short strips.`,ua:`Всипте борошно в гарячу рідину й енергійно розмішайте до утворення тіста; трохи охолодіть, введіть яйця й відсадіть смужками.`,t:[`mixing`],m:5,i:[[`all-purpose-flour`,185,`g`],[`chicken-egg`,2,`pcs`]]},{en:`Fry shaped portions in small batches in oil heated to about 170–175°C for about 14 minutes, until golden; drain on a rack.`,ua:`Смажте сформовані вироби невеликими партіями в олії температурою приблизно 170–175°C близько 14 хвилин до золотистості; викладіть на решітку.`,t:[`deep-frying`],m:14,i:[[`sunflower-oil`,700,`ml`]]},{en:`Melt the chocolate into warm milk with cinnamon, whisking until you have a thick dipping sauce; do not scorch.`,ua:`Розтопіть шоколад у теплому молоці з корицею, збиваючи до густого соусу для вмочування, не допускаючи підгоряння.`,t:[`mixing`],m:5,i:[[`dark-chocolate`,190,`g`],[`whole-cow-milk`,200,`ml`],[`ground-cinnamon`,2,`g`]]}];var c={slug:o,id:t,country:`ES`,region:a,servings:8,minutes:29,title:s,text:u,steps:h};export{n as country,c as default,t as id,l as minutes,a as region,r as servings,o as slug,h as steps,u as text,s as title};